/**
 * scripts/bundle-worker.js
 *
 * Pre-bundles merge-worker.ts + its yjs dependency into a single
 * self-contained JS string that can be loaded as an inline blob Worker
 * without any external network requests.
 *
 * Run: node scripts/bundle-worker.js
 */

const esbuild = require('esbuild');
const fs = require('fs');
const path = require('path');

const WORKER_ENTRY = path.resolve(__dirname, '../src/merge-worker.ts');
const OUTPUT_DIR = path.resolve(__dirname, '../src/generated');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'merge-worker-blob.ts');

async function main() {
    // Bundle merge-worker.ts + yjs into a single IIFE
    const result = await esbuild.build({
        entryPoints: [WORKER_ENTRY],
        bundle: true,
        format: 'iife',
        platform: 'browser',
        target: 'es2020',
        write: false,
        minify: true,
    });

    const bundledCode = result.outputFiles[0].text;

    // Escape backticks and backslashes for template literal embedding
    const escaped = bundledCode
        .replace(/\\/g, '\\\\')
        .replace(/`/g, '\\`')
        .replace(/\$/g, '\\$');

    const tsContent = `// AUTO-GENERATED by scripts/bundle-worker.js — DO NOT EDIT
// Contains merge-worker.ts + yjs bundled as a self-contained IIFE.
export const MERGE_WORKER_CODE = \`${escaped}\`;
`;

    // Ensure output directory exists
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
    fs.writeFileSync(OUTPUT_FILE, tsContent, 'utf-8');

    const sizeKB = (Buffer.byteLength(bundledCode) / 1024).toFixed(1);
    console.log(`✓ Bundled merge worker (${sizeKB} KB) → ${path.relative(process.cwd(), OUTPUT_FILE)}`);
}

main().catch((err) => {
    console.error('Failed to bundle merge worker:', err);
    process.exit(1);
});
